"""Recompress existing deflated entries at level 9; align and re-sign with the SAME build key."""
from pathlib import Path
import os
import re
import subprocess
import sys
import tempfile
import zipfile


def recompress(source, destination):
    with zipfile.ZipFile(source) as original, zipfile.ZipFile(destination, 'w') as compact:
        for info in original.infolist():
            # JAR signature files are regenerated by apksigner. Do not remove services/licenses.
            if re.fullmatch(r'META-INF/(?:MANIFEST\.MF|[^/]+\.(?:RSA|DSA|EC|SF))', info.filename, re.I):
                continue
            # Retain STORED entries (notably resources.arsc, required on modern Android).
            compact.writestr(info, original.read(info.filename), compress_type=info.compress_type, compresslevel=9)


def main():
    tools = sorted((Path(os.environ['ANDROID_HOME']) / 'build-tools').glob('*/apksigner'))
    assert tools, 'Android signing tools missing'
    tool = tools[-1].parent
    directory = Path('android/app/build/outputs/apk/release')
    apks = sorted(directory.glob('*.apk'))
    assert len(apks) == 3, 'Expected exactly three compact ABI builds'
    for apk in apks:
        with tempfile.TemporaryDirectory() as temporary:
            temporary = Path(temporary)
            packed, aligned, signed = [temporary / name for name in ('packed.apk', 'aligned.apk', 'signed.apk')]
            recompress(apk, packed)
            subprocess.run([str(tool / 'zipalign'), '-P', '16', '-f', '4', str(packed), str(aligned)], check=True)
            subprocess.run([str(tool / 'apksigner'), 'sign', '--ks', 'android/app/debug.keystore',
                            '--ks-key-alias', 'androiddebugkey', '--ks-pass', 'pass:android',
                            '--key-pass', 'pass:android', '--out', str(signed), str(aligned)], check=True)
            subprocess.run([str(tool / 'apksigner'), 'verify', str(signed)], check=True)
            if signed.stat().st_size < apk.stat().st_size:
                apk.write_bytes(signed.read_bytes())
            print(f'Level-9 compression complete: {apk.name}, {apk.stat().st_size} bytes')


if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        reason = str(error) if isinstance(error, AssertionError) else type(error).__name__
        print('::error title=APK compression::'+reason, flush=True)
        sys.exit(1)
